/** Shape of src/data/atlas/atlasTree.json, generated by scripts/update-atlas-tree.mjs. */

export type AtlasNodeKind = "root" | "normal" | "notable" | "keystone" | "wormhole";

export interface AtlasNode {
  id: number;
  kind: AtlasNodeKind;
  name: string;
  x: number;
  y: number;
  stats?: string[];
  /** Notables that let the player pick one effect. */
  choices?: string[];
  /** League mechanic the node belongs to (Breach, Delirium…). */
  region?: string;
}

export interface AtlasRegion {
  name: string;
  x: number;
  y: number;
}

export interface AtlasTreeData {
  version: string;
  totalPoints: number;
  /** The Atlas centre, which every player starts with. */
  root: number;
  bounds: { minX: number; minY: number; maxX: number; maxY: number };
  regions: AtlasRegion[];
  nodes: AtlasNode[];
  edges: [number, number][];
}
